// Construit le prompt final Script Agent
const video    = $node['Get Video Details'].json[0];
const ragCtx   = $node['Get RAG Context'].json || [];
const patterns = $node['Get Winning Patterns'].json || [];

// Formate le contexte RAG
const ragText = ragCtx.length > 0
  ? ragCtx.map(c => `[${c.context_type.toUpperCase()}] ${c.title ? c.title + ':\n' : ''}${c.content}`).join('\n\n')
  : 'Aucun contexte client disponible.';

// Formate les patterns gagnants
const patternsText = patterns.length > 0
  ? patterns.map(p => `- Type: ${p.element_type} | Valeur: "${p.element_value}" | Engagement: ${p.avg_engagement_rate ? (p.avg_engagement_rate * 100).toFixed(1) + '%' : 'N/A'}`).join('\n')
  : 'Pas encore de patterns disponibles pour ce client.';

const userPrompt = `BRIEF CLIENT :\n${video.brief || 'Non spécifié'}\n\nOBJECTIF : ${video.objective || 'Non spécifié'}\nPLATEFORME : ${video.platform || 'Instagram Reels'}\nFORMAT : ${video.format || 'Vidéo courte 15s'}\nAUDIENCE : ${video.target_audience || 'Non spécifié'}\nLANGUE : ${video.language || 'fr-CA'}\n\nCONTEXTE CLIENT (RAG) :\n${ragText}\n\nPATTERNS GAGNANTS :\n${patternsText}`;

return [{
  json: {
    video_id:    video.id,
    client_id:   video.client_id,
    user_prompt: userPrompt,
    video:       video
  }
}];

