// Valide et parse la réponse OpenRouter
const response = $input.first().json;
const video_id  = $node['Build Prompt'].json.video_id;
const client_id = $node['Build Prompt'].json.client_id;

const usage = response.usage || {};
const rawContent = response.choices?.[0]?.message?.content;

if (!rawContent) {
  throw new Error('OpenRouter returned empty content');
}

let parsed;
try {
  parsed = JSON.parse(rawContent);
} catch (e) {
  throw new Error(`Invalid JSON from OpenRouter: ${e.message}`);
}

// Validation champs obligatoires
const required = ['script', 'shot_list', 'prompt_comfyui', 'prompt_fal', 'negative_prompt'];
for (const field of required) {
  if (!parsed[field]) throw new Error(`Missing field: ${field}`);
}

if (!parsed.script.hook || !parsed.script.body || !parsed.script.cta) {
  throw new Error('Missing script.hook, script.body or script.cta');
}

if (!Array.isArray(parsed.shot_list) || parsed.shot_list.length < 3 || parsed.shot_list.length > 5) {
  throw new Error(`shot_list must have 3-5 scenes, got ${parsed.shot_list?.length}`);
}

// Coût approximatif (OpenRouter retourne en USD)
const cost_usd = (usage.prompt_tokens * 0.000003) + (usage.completion_tokens * 0.000015);

return [{
  json: {
    video_id,
    client_id,
    script_data:        parsed,
    prompt_tokens:      usage.prompt_tokens || 0,
    completion_tokens:  usage.completion_tokens || 0,
    cost_usd,
    model_used:         response.model || 'unknown'
  }
}];

